(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-957":{scenario:{company:"Red River Snack Foods",supervisor:{name:"Lương Đức Thịnh",role:{vi:"Giám đốc Vận hành",en:"Operations Director"}},ref_code:"OEE-W45",title:{vi:"Gọi đúng tổn thất. Tính đúng OEE. Không đánh đổi an toàn.",en:"Name the loss. Compute OEE right. Never trade safety."},brief:{vi:"Bạn hoàn thiện báo cáo hiệu suất OEE-W45 cho dây chuyền đóng gói bánh quy ca 1. Ca dài 480 phút, nghỉ giữa ca có kế hoạch 30 phút; hỏng máy và chuyển đổi sản phẩm làm dừng 45 phút. Tốc độ lý tưởng 120 gói/phút; tổng sản lượng 43740 gói, trong đó 41553 gói đạt. Máy đóng gói kẹt nhiều lần dưới 2 phút và chạy chậm. Sửa phân loại tổn thất và chỉ số OEE (%), rồi lập báo cáo có căn cứ.",en:"You are finalising performance report OEE-W45 for the biscuit packing line, shift 1. The shift is 480 minutes with a planned 30-minute break; breakdowns and product changeovers stopped the line for 45 minutes. Ideal rate is 120 packs per minute; total output was 43740 packs, of which 41553 were good. The packer jammed many times for under 2 minutes and ran slow. Correct the loss category and the OEE (%), then write an evidence-based report."},reference_title:{vi:"Nhật ký ca & chuẩn tính OEE đã duyệt · OEE-W45",en:"Approved shift log & OEE standard · OEE-W45"},fields:[{id:"LOSS_CLASS",label:{vi:"Nhóm tổn thất của dừng ngắn & chạy chậm",en:"Loss category of minor stops & slow running"},initial:"AVAILABILITY",expected:"PERFORMANCE",choices:["AVAILABILITY","PERFORMANCE","QUALITY"],reference:"Bảng 6 tổn thất lớn (Six Big Losses)",hint:{vi:"Dừng ngắn và giảm tốc độ làm giảm hiệu suất; hỏng máy và chuyển đổi mới thuộc nhóm thời gian sẵn sàng.",en:"Minor stops and reduced speed lower performance; breakdowns and changeovers belong to availability."}},{id:"OEE_PCT",label:{vi:"OEE ca 1 (%)",en:"Shift 1 OEE (%)"},initial:"72.14",expected:"76.95",reference:"Nhật ký thời gian & sản lượng ca 1",ref_value:{vi:"Ca 480 phút; nghỉ kế hoạch 30; dừng 45; 120 gói/phút; tổng 43740; đạt 41553",en:"Shift 480 min; planned break 30; downtime 45; 120 packs/min; total 43740; good 41553"},hint:{vi:"Thời gian sản xuất kế hoạch phải trừ nghỉ có kế hoạch trước khi tính tỷ lệ sẵn sàng.",en:"Planned production time excludes the planned break before availability is calculated."}}],sop32:{vi:"OEE = A x P x Q; A = thời gian chạy / (ca - nghỉ có kế hoạch); P = tổng sản lượng / (thời gian chạy x tốc độ lý tưởng); Q = sản phẩm đạt / tổng sản lượng; ghi % làm tròn 2 chữ số.",en:"OEE = A x P x Q; A = run time / (shift - planned break); P = total output / (run time x ideal rate); Q = good output / total output; report % to 2 decimals."},context:{label:"MES / OEE-W45",metrics:[{label:{vi:"Thời gian ca",en:"Shift time"},value:"480 min"},{label:{vi:"Dừng không kế hoạch",en:"Unplanned downtime"},value:"45 min"},{label:{vi:"Sản lượng tổng / đạt",en:"Total / good output"},value:"43740 / 41553"}]},crisis:{vi:"Giám đốc nhà máy nhắn: “Máy dò kim loại báo lỗi liên tục, tắt nó đi cho chuyền chạy, đơn 20 tấn phải xuất tối nay. Máy quá nhạy thôi, lô trước có sao đâu.”",en:"The plant director messages you: “The metal detector keeps rejecting, switch it off so the line can run, the 20-tonne order ships tonight. It's just oversensitive, the last lot was fine.”"},options:{safe:{vi:"Không tắt máy dò kim loại vì đây là CCP; cách ly sản phẩm từ lần thử mẫu chuẩn đạt gần nhất, gọi bảo trì và QA kiểm tra, báo giám đốc vận hành, khách hàng về khả năng trễ và bố trí ca bù.",en:"Do not bypass the metal detector, it is a CCP; hold product since the last passing test piece check, call maintenance and QA, inform the operations director and customer of a possible delay and plan a catch-up shift."},shortcut:{vi:"Tắt máy dò kim loại để chạy kịp đơn hàng, ghi chú kiểm tra lại sau.",en:"Switch off the metal detector to make the order and note a check for later."},wait:{vi:"Dừng chuyền, chờ giám đốc nhà máy tự xử lý và không báo ai.",en:"Stop the line, wait for the plant director to sort it out and tell no one."}},questions:{vi:["Vì sao dừng ngắn thuộc nhóm PERFORMANCE và OEE ca 1 là 76.95%? Số liệu nào chứng minh?","Bạn cân bằng tiến độ đơn hàng 20 tấn với yêu cầu không bỏ qua CCP máy dò kim loại thế nào?"],en:["Why do minor stops count as PERFORMANCE and why is shift 1 OEE 76.95%? Which data proves it?","How do you balance the 20-tonne order deadline with the rule never to bypass the metal detector CCP?"]},hints:{vi:["Đặt nhật ký dừng máy cạnh bảng 6 tổn thất lớn và phân loại từng sự kiện.","Tính lần lượt A, P, Q từ thời gian sản xuất kế hoạch đã trừ nghỉ theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không được vô hiệu hóa thiết bị kiểm soát CCP; mọi áp lực phải báo cáo."],en:["Place the stop log next to the Six Big Losses table and classify each event.","Calculate A, P and Q in turn from planned production time net of the break as in SOP 3.2.","Re-read SOP 4.2: CCP control devices are never disabled; any pressure must be escalated."]}},learning:{summary:{vi:"Quản lý sản xuất nhà máy chế biến thực phẩm lập kế hoạch và điều phối con người, máy móc, nguyên liệu để sản xuất đúng sản lượng, đúng chất lượng, an toàn và chi phí tối ưu. Nghề đòi hỏi thành thạo chỉ số vận hành như OEE, năng suất lao động, tiêu hao nguyên liệu, kết hợp với hệ thống an toàn thực phẩm, an toàn lao động và kỹ năng lãnh đạo đội ngũ theo ca.",en:"A food plant production manager plans and coordinates people, machines and materials to deliver the right volume at the right quality, safely and at optimal cost. The role requires mastery of operating metrics such as OEE, labour productivity and material usage, combined with food safety and occupational safety systems and the ability to lead shift teams."},responsibilities:{vi:["Lập kế hoạch sản xuất ngày, tuần theo đơn hàng, tồn kho và năng lực dây chuyền.","Điều phối nhân sự ca, bảo trì, kho và QA để dây chuyền chạy ổn định.","Theo dõi OEE, tiêu hao nguyên vật liệu, phế phẩm và triển khai cải tiến liên tục.","Bảo đảm tuân thủ HACCP, GMP, an toàn lao động và môi trường tại xưởng.","Báo cáo hiệu suất, chi phí và xử lý sự cố với ban giám đốc, khách hàng."],en:["Plan daily and weekly production from orders, stock and line capacity.","Coordinate shift staff, maintenance, warehouse and QA to keep lines stable.","Track OEE, material usage and scrap and drive continuous improvement.","Ensure HACCP, GMP, occupational safety and environmental compliance on the floor.","Report performance and cost and handle incidents with management and customers."]},competencies:[{name:{vi:"Lập kế hoạch & điều độ",en:"Planning & scheduling"},desc:{vi:"Cân đối đơn hàng, nguyên liệu, nhân lực và thời gian chuyển đổi để đạt kế hoạch.",en:"Balance orders, materials, labour and changeovers to hit the plan."}},{name:{vi:"Quản lý hiệu suất (OEE)",en:"Performance management (OEE)"},desc:{vi:"Đo đúng, phân loại đúng tổn thất và chọn ưu tiên cải tiến có tác động lớn nhất.",en:"Measure and classify losses correctly and prioritise the highest-impact improvements."}},{name:{vi:"Cải tiến tinh gọn",en:"Lean improvement"},desc:{vi:"Áp dụng 5S, SMED, Kaizen, giải quyết vấn đề tận gốc với nhóm sản xuất.",en:"Apply 5S, SMED and Kaizen and solve root causes with the production team."}},{name:{vi:"An toàn thực phẩm & lao động",en:"Food & workplace safety"},desc:{vi:"Không đánh đổi CCP, vệ sinh và an toàn người lao động để lấy sản lượng.",en:"Never trade CCPs, hygiene or worker safety for output."}},{name:{vi:"Lãnh đạo đội ngũ ca",en:"Shift team leadership"},desc:{vi:"Giao việc rõ, huấn luyện tại chỗ và xây dựng văn hóa báo cáo sự cố.",en:"Assign clearly, coach on the floor and build a culture of reporting issues."}}],knowledge:{vi:["OEE và 6 tổn thất lớn trong bảo trì năng suất toàn diện (TPM).","Sản xuất tinh gọn: 5S, SMED, Kaizen, quản lý trực quan.","ISO 22000, HACCP, GMP và vai trò của các CCP như máy dò kim loại, nhiệt độ nấu.","ISO 45001 về hệ thống quản lý an toàn, sức khỏe nghề nghiệp.","Hoạch định nhu cầu vật tư (MRP) và lập kế hoạch bán hàng & vận hành (S&OP)."],en:["OEE and the Six Big Losses in total productive maintenance (TPM).","Lean manufacturing: 5S, SMED, Kaizen and visual management.","ISO 22000, HACCP, GMP and the role of CCPs such as metal detection and cooking temperature.","ISO 45001 on occupational health and safety management systems.","Material requirements planning (MRP) and sales and operations planning (S&OP)."]},tools:["Hệ thống điều hành sản xuất (MES)","Phần mềm ERP","Bảng điều khiển OEE thời gian thực","Bảng quản lý trực quan tại chuyền","Máy dò kim loại & mẫu thử chuẩn"],kpis:{vi:["OEE từng dây chuyền so với mục tiêu.","Tỷ lệ đơn hàng giao đúng hạn, đủ số lượng.","Tiêu hao nguyên liệu và tỷ lệ phế phẩm.","Số sự cố an toàn thực phẩm và tai nạn lao động (mục tiêu bằng 0)."],en:["OEE per line versus target.","On-time, in-full delivery rate.","Material usage and scrap rate.","Food safety incidents and workplace accidents (target zero)."]},day:[{time:"07:00",vi:"Họp giao ca, xem OEE ca đêm, sự cố và kế hoạch trong ngày.",en:"Shift handover meeting reviewing night-shift OEE, incidents and today's plan."},{time:"08:00",vi:"Đi kiểm tra hiện trường (gemba), xác nhận thử mẫu chuẩn máy dò kim loại.",en:"Gemba walk and confirmation of metal detector test piece checks."},{time:"10:00",vi:"Điều chỉnh kế hoạch khi nguyên liệu về trễ, sắp xếp lại thứ tự chạy.",en:"Adjust the plan for late materials and resequence production runs."},{time:"14:00",vi:"Họp cải tiến giảm thời gian chuyển đổi sản phẩm theo SMED.",en:"Improvement meeting to cut changeover time using SMED."},{time:"16:30",vi:"Báo cáo ngày, chuẩn bị kế hoạch và nhân sự cho ca tối.",en:"Daily report and preparation of the plan and staffing for the evening shift."}],mistakes:{vi:["Tính OEE trên toàn bộ thời gian ca, không trừ nghỉ có kế hoạch, làm sai chuẩn so sánh.","Xếp dừng ngắn vào nhóm sẵn sàng, che mất vấn đề tốc độ của máy đóng gói.","Bỏ qua cảnh báo CCP để chạy kịp sản lượng."],en:["Calculating OEE on the full shift without removing planned breaks, distorting comparisons.","Classing minor stops as availability and hiding the packer's speed problem.","Ignoring a CCP alarm to make volume."]},career:[{vi:"Tổ trưởng sản xuất",en:"Production team leader"},{vi:"Trưởng ca sản xuất",en:"Shift production supervisor"},{vi:"Quản lý sản xuất nhà máy",en:"Plant production manager"},{vi:"Giám đốc nhà máy",en:"Plant director"}],glossary:[{term:"OEE",vi:"Hiệu suất thiết bị tổng thể = sẵn sàng x hiệu suất x chất lượng.",en:"Overall equipment effectiveness = availability x performance x quality."},{term:"Six Big Losses",vi:"6 tổn thất lớn: hỏng máy, chuyển đổi, dừng ngắn, giảm tốc, phế phẩm khởi động, phế phẩm sản xuất.",en:"Breakdowns, changeovers, minor stops, reduced speed, startup rejects and production rejects."},{term:"SMED",vi:"Phương pháp chuyển đổi khuôn, sản phẩm trong vài phút bằng cách tách việc trong và ngoài máy.",en:"Single-minute exchange of die: cutting changeovers by separating internal and external tasks."},{term:"Gemba",vi:"Hiện trường nơi giá trị được tạo ra; quản lý đi gemba để thấy vấn đề thật.",en:"The place where value is created; managers walk the gemba to see real problems."},{term:"CCP",vi:"Điểm kiểm soát tới hạn trong HACCP, ví dụ máy dò kim loại hoặc nhiệt độ nấu.",en:"Critical control point in HACCP, such as metal detection or cooking temperature."}],quiz:[{q:{vi:"Sẵn sàng 0.9, hiệu suất 0.8, chất lượng 0.95. OEE bằng bao nhiêu?",en:"Availability 0.9, performance 0.8, quality 0.95. What is the OEE?"},options:{vi:["90%","68.4%","85%","72%"],en:["90%","68.4%","85%","72%"]},answer:1,explain:{vi:"OEE = 0.9 x 0.8 x 0.95 = 0.684, tức 68.4%.",en:"OEE = 0.9 x 0.8 x 0.95 = 0.684, or 68.4%."}},{q:{vi:"Thời gian chuyển đổi sản phẩm thuộc nhóm tổn thất nào trong OEE?",en:"Which OEE loss category does product changeover time belong to?"},options:{vi:["Chất lượng","Hiệu suất","Sẵn sàng (Availability)","Không tính vào OEE"],en:["Quality","Performance","Availability","Not counted in OEE"]},answer:2,explain:{vi:"Chuyển đổi và hỏng máy làm dừng chuyền có thời lượng đáng kể nên thuộc nhóm sẵn sàng.",en:"Changeovers and breakdowns stop the line for significant time, so they reduce availability."}},{q:{vi:"Máy dò kim loại báo lỗi khi đang chạy đơn gấp. Bạn làm gì?",en:"The metal detector alarms during an urgent order. What do you do?"},options:{vi:["Tắt máy dò","Chạy tiếp và ghi chú","Giảm độ nhạy máy","Dừng, cách ly sản phẩm từ lần thử đạt gần nhất, gọi QA và bảo trì"],en:["Switch the detector off","Keep running and add a note","Lower the sensitivity","Stop, hold product since the last passing check and call QA and maintenance"]},answer:3,explain:{vi:"Máy dò kim loại là CCP; vô hiệu hóa nó có thể đưa dị vật kim loại tới người tiêu dùng.",en:"The metal detector is a CCP; disabling it can let metal fragments reach consumers."}},{q:{vi:"Mục tiêu của SMED là gì?",en:"What is the goal of SMED?"},options:{vi:["Giảm thời gian chuyển đổi sản phẩm","Tăng số công nhân","Kéo dài ca làm việc","Thay thế bảo trì định kỳ"],en:["Cut product changeover time","Add more workers","Extend the shift","Replace planned maintenance"]},answer:0,explain:{vi:"SMED tách công việc làm được khi máy chạy ra ngoài để rút ngắn thời gian dừng chuyển đổi.",en:"SMED moves tasks that can be done while running outside the stop to shorten changeovers."}}],tools_en:["Manufacturing execution system (MES)","ERP software","Real-time OEE dashboard","Line-side visual management board","Metal detector & certified test pieces"]}}})})(window.KKR);
